package com.bookstore.order.service;
import com.bookstore.book.repository.BookRepository; import com.bookstore.cart.repository.CartRepository; import com.bookstore.user.repository.UserRepository; import com.bookstore.order.dto.OrderRequest; import com.bookstore.order.entity.*; import com.bookstore.order.repository.OrderRepository; import jakarta.transaction.Transactional; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.BigDecimal;
@Service public class OrderService { private final OrderRepository orders; private final BookRepository books; private final UserRepository users; private final CartRepository carts; public OrderService(OrderRepository orders,BookRepository books,UserRepository users,CartRepository carts){this.orders=orders;this.books=books;this.users=users;this.carts=carts;} @Transactional public Order create(String username,OrderRequest r){var o=new Order();o.setUser(users.findByUsername(username).orElseThrow());o.setCustomerName(r.customerName());o.setCustomerEmail(r.customerEmail());o.setShippingAddress(r.shippingAddress());o.setPhone(r.phone());var total=BigDecimal.ZERO;for(var i:r.items()){var b=books.findById(i.bookId()).orElseThrow();if(b.getStock()<i.quantity())throw new IllegalArgumentException("Not enough stock");b.setStock(b.getStock()-i.quantity());var item=new OrderItem();item.setOrder(o);item.setBook(b);item.setQuantity(i.quantity());item.setUnitPrice(b.getPrice());o.getItems().add(item);total=total.add(b.getPrice().multiply(BigDecimal.valueOf(i.quantity())));}o.setTotalAmount(total);var saved=orders.save(o);var cart=carts.findByUserUsername(username).orElse(null);if(cart!=null){cart.getItems().clear();carts.save(cart);}return saved;} }
